import demand from './cityDemand.json';

// ============================================================================
// CITY PAGES. Built from measured search demand, not from a city list.
// ============================================================================
//
// cityDemand.json is generated by ~/Axelis/aeo-tracker/coverage.py, which asks
// Google autocomplete three service questions about every city in the registry
// and keeps only the phrases that actually name that city. 273 cities measured,
// 161 returned real demand.
//
// TWO RULES THIS FILE EXISTS TO ENFORCE:
//
// 1. A city only gets its own page if it has enough measured demand to justify
//    one. Publishing 161 near-identical pages is the textbook definition of a
//    doorway set, and Google removes them -- which would cost the whole domain,
//    not just the thin pages. Cities under the threshold are covered as
//    sections on their state page instead. Every one of the 161 is still
//    reachable; the page count just follows the data.
//
// 2. Axelis has exactly TWO offices: Bengaluru and Bilaspur. Counselling
//    everywhere else is remote, over Google Meet. No page may imply an office,
//    a branch or a local address where none exists, and none of these pages
//    carries LocalBusiness schema -- that is reserved for the two real
//    premises in src/data/offices.js. Claiming a local presence we do not have
//    is both a Google Business Profile violation and a misleading-advertising
//    problem under the Consumer Protection Act.
// ============================================================================

// A city needs at least this many distinct measured phrases to earn a page.
export const PAGE_THRESHOLD = 5;

export const OFFICES_REAL = ['Bengaluru', 'Bilaspur'];

export const CITIES = demand;

// A city earns a page on demand OR because we have an office there. Bilaspur
// measured only 2 phrases and was silently dropped, which 404'd the page for
// the registered office and the one city with all 75 of our reviews. Search
// demand is not the only reason a page has to exist.
const earnsPage = (c) => c.phrases >= PAGE_THRESHOLD || OFFICES_REAL.includes(c.city);

export const CITY_PAGES = demand.filter(earnsPage);

export const ROLLUP_CITIES = demand.filter((c) => !earnsPage(c));

export const CITY_SLUGS = CITY_PAGES.map((c) => c.slug);

export const cityBySlug = (slug) => CITY_PAGES.find((c) => c.slug === slug);

export const citiesInState = (state) => demand.filter((c) => c.state === state);

export const STATES = [...new Set(demand.map((c) => c.state))].sort();

// True only for the two cities where Axelis actually has premises.
export const hasOffice = (city) => OFFICES_REAL.includes(city);

/**
 * The questions students in this city actually type, taken from the measured
 * set rather than invented. This is what makes one city page different from
 * another: the demand data differs, so the questions differ.
 */
export const questionsFor = (c) =>
  (c.queries || []).filter((q) => q && !/reviews|photos|salary/i.test(q));
